add_action( 'init', 'perfectpixel_disable_feeds_links' );
foreach ( array( 'do_feed', 'do_feed_rdf', 'do_feed_rss', 'do_feed_rss2', 'do_feed_atom', 'do_feed_rss2_comments', 'do_feed_atom_comments' ) as $perfectpixel_feed_hook ) {
	add_action( $perfectpixel_feed_hook, 'perfectpixel_disable_feeds_redirect', 1 );
}
unset( $perfectpixel_feed_hook );

function perfectpixel_disable_feeds_links() {
	remove_action( 'wp_head', 'feed_links', 2 );
	remove_action( 'wp_head', 'feed_links_extra', 3 );
}

function perfectpixel_disable_feeds_redirect() {
	$url = home_url( '/' );
	if ( is_singular() ) {
		$url = get_permalink( get_queried_object_id() );
	} elseif ( is_category() || is_tag() || is_tax() ) {
		$term_link = get_term_link( get_queried_object() );
		$url       = is_wp_error( $term_link ) ? $url : $term_link;
	} elseif ( is_author() ) {
		$url = get_author_posts_url( get_queried_object_id() );
	}
	wp_safe_redirect( $url, 301 );
	exit;
}
